INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷102·隐帝本纪·乾祐二年二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/jiuwudaishi-102-february-949/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年二月，段落 jiu-wudaishi-205deb4a7860-p002471；已核上下文及传主，纸本及异文待核。", "id": "89ff8933-0f31-5fb0-9683-351b9cea1ff9"}, {"title": "旧五代史·卷102·隐帝本纪·乾祐二年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/jiuwudaishi-102-january-949/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年正月，段落 jiu-wudaishi-205deb4a7860-p002470；已核上下文及传主，纸本及异文待核。", "id": "c566cce3-70bd-568f-9459-80e7acba4603"}, {"title": "旧五代史·卷102·隐帝本纪·乾祐二年五月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/jiuwudaishi-102-may-949/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年五月，段落 jiu-wudaishi-205deb4a7860-p002474；已核上下文及传主，纸本及异文待核。", "id": "5f60206d-10da-54a0-9b9b-aed2fca2bf32"}, {"title": "旧五代史·卷107·史弘肇传附史德充", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/jiuwudaishi-107-shi-dechong/source.txt", "note": "《旧五代史》卷107·史弘肇传附史德充，段落 jiu-wudaishi-205deb4a7860-p002559；已核上下文及传主，纸本及异文待核。", "id": "c30a59d6-2066-5c5f-8c5e-77e17764312d"}, {"title": "旧五代史·卷110·周太祖纪·河中之役", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/jiuwudaishi-110-guo-hezhong-949/source.txt", "note": "《旧五代史》卷110·周太祖纪·河中之役，段落 jiu-wudaishi-205deb4a7860-p002635；已核上下文及传主，纸本及异文待核。", "id": "3215db1b-e4b9-597e-b981-6b30a3a4ae28"}, {"title": "辽史·卷6·穆宗纪·姓名亲支", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/liaoshi-006-jing-shulu-identity/source.txt", "note": "《辽史》卷6·穆宗纪·姓名亲支，段落 liaoshi-7cd182a20e67-p000624；已核上下文及传主，纸本及异文待核。", "id": "51c47263-518b-5971-b6a1-46494110a1c0"}, {"title": "宋史·卷271·李韬传·河中交战", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/songshi-271-li-tao-hezhong/source.txt", "note": "《宋史》卷271·李韬传·河中交战，段落 songshi-9c6e46fee832-p058977；已核上下文及传主，纸本及异文待核。", "id": "dae6804a-cb6f-5799-bfd9-a0ff8fc2e9ea"}, {"title": "宋史·卷274·王继勋传·河中交战", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/songshi-274-wang-jixun-hezhong/source.txt", "note": "《宋史》卷274·王继勋传·河中交战，段落 songshi-9c6e46fee832-p059155；已核上下文及传主，纸本及异文待核。", "id": "d07634ea-f56a-5353-800f-c7541dff3b01"}, {"title": "资治通鉴·卷288·乾祐二年·正月至五月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/tongjian-288-949-january-may/source.txt", "note": "《资治通鉴》卷288·乾祐二年·正月至五月，段落 zizhi-tongjian-a63549944a71-p003422；已核上下文及传主，纸本及异文待核。", "id": "b2787966-ee28-54a5-bb50-954e25081121"}, {"title": "新五代史·卷17·晋家人传·安太妃", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/xinwudaishi-017-an-taifei/source.txt", "note": "《新五代史》卷17·晋家人传·安太妃，段落 xin-wudaishi-b08f244b9241-p000576；已核上下文及传主，纸本及异文待核。", "id": "ccfab8bd-ba1a-519e-914b-5d9b91db2e69"}, {"title": "新五代史·卷17·晋家人传·出帝迁建州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/xinwudaishi-017-jin-jianzhou-949/source.txt", "note": "《新五代史》卷17·晋家人传·出帝迁建州，段落 xin-wudaishi-b08f244b9241-p000572；已核上下文及传主，纸本及异文待核。", "id": "bb2d4fa4-9cfb-5b51-bcfb-9d7b6f718fb6"}, {"title": "新五代史·卷17·晋家人传·高祖李皇后", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74625032a86ac7faa4033ef6a6ab3a883887537c/content/books/zizhi-tongjian/vol-288/year-0949/part-01/sources/library/xinwudaishi-017-li-empress-identity/source.txt", "note": "《新五代史》卷17·晋家人传·高祖李皇后，段落 xin-wudaishi-b08f244b9241-p000558；已核上下文及传主，纸本及异文待核。", "id": "e46d29dc-4a7e-5804-bfcf-2783119dad4b"}, {"title": "旧五代史·卷107·史弘肇传·刑杀与军狱", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/jiuwudaishi-107-shi-punishments/source.txt", "note": "《旧五代史》卷107·史弘肇传·刑杀与军狱，段落 jiu-wudaishi-205deb4a7860-p002555；已核上下文及传主，纸本及异文待核。", "id": "38061fa7-243a-5f22-8624-a0d83925de8f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "白文珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。944年九月在七里烽击败契丹；新史记丙子，旧史壬辰记录太原奏报。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4144a98b-cc52-5b8e-afec-6ad9ed55b845"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "王继勋（李守贞将）", "aliases": ["王继勋（平陆将领）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "平陆人，李守贞部将。948年李守贞自称秦王后，派他率兵占据潼关。与闽国王氏宗族成员和宋代同名人物分开，未作无证合并。生卒年未载。", "biography": null, "status": "draft", "id": "cebf1403-38a6-5f4e-b202-577b1ed71892"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}, {"name": "阎晋卿", "aliases": ["閻晉卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "忻州人，后汉客省使。949年正月河中军夜袭后汉营寨时，提醒将士可以凭黄纸甲在火光下辨认敌军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "cd541c62-d1b8-5017-afb5-ae81ba6585ac"}, {"name": "李韬", "aliases": ["李韜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉裨将。949年正月河中军夜袭营寨时，持槊率先迎战，众人跟随。《宋史》记河朔人、善用槊，所记交战过程也有更详细的内容。生卒年尚未录入。", "biography": null, "status": "draft", "id": "66c52cee-0c23-53a0-b3d7-e70aa1470bf9"}, {"name": "李审", "aliases": ["李審"], "era": "五代十国", "birth_year": null, "death_year": 949, "description": "郭威的亲近将领。郭威禁止军中私下饮酒后，李审因早晨饮少量酒违反军令，被处死示众。949年条下记载此事，具体日未载。其他经历尚未确认。", "biography": null, "status": "draft", "id": "2206fe10-32f8-57f0-82f5-9b769ccbbaef"}, {"name": "安思谦", "aliases": ["安思謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安思谦，茶酒库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "6ec752d6-91f9-5760-8ea8-c552e6369345"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "李彝殷", "aliases": ["李彜殷", "李彝兴", "李彝興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李彝殷，行军司马、权知军州事者。", "biography": null, "status": "draft", "id": "22edc111-ae26-5bce-a26b-3ae072425377"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "皇甫晖", "aliases": ["皇甫暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：皇甫晖。", "biography": null, "status": "draft", "id": "a1bbff11-3e05-52a8-a3c1-7e24adc029a5"}, {"name": "咸师朗", "aliases": ["咸師朗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蒙城镇将。949年南唐派皇甫晖到海州、泗州招纳淮北势力时，向皇甫晖投降。生卒年与其他经历未载。", "biography": null, "status": "draft", "id": "dc4e6f3f-cdad-5934-82a9-e901cc6f65dc"}, {"name": "成德钦", "aliases": ["成德欽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉徐州将领。949年二月击败南唐军，《旧五代史》称徐州巡检使，并载其奏报；战果人数和战场地名的字形与《通鉴》略有不同，分别保留。生卒年未载。", "biography": null, "status": "draft", "id": "cd024ceb-2003-58bc-a71d-d68cdf3651d1"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "安氏（石重贵母）", "aliases": ["安氏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安氏（石重贵母），石重贵之母亲。", "biography": null, "status": "draft", "id": "007fcf3c-6da4-54ec-9554-a112cebe061f"}, {"name": "耶律璟", "aliases": ["耶律述律", "述律王", "寿安王", "壽安王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律德光的长子，小字述律，封寿安王。《资治通鉴》949年条称述律王，记他派骑兵带走石重贵的宠姬赵氏、聂氏；《辽史》穆宗纪可核对姓名和亲支。949年时仍以述律王身份见于记载。", "biography": null, "status": "draft", "id": "81fb2030-5792-5006-be3c-0909be18feec"}, {"name": "赵氏（石重贵宠姬）", "aliases": ["趙氏（石重貴寵姬）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石重贵的宠姬，个人名字与生卒年未载。949年石重贵迁到建州后不久，被述律王耶律璟派骑兵带走。没有据此认定她与耶律璟建立婚姻关系。", "biography": null, "status": "draft", "id": "ac61e23f-4c35-573c-b5a5-5d16d1e5a9e5"}, {"name": "聂氏（石重贵宠姬）", "aliases": ["聶氏（石重貴寵姬）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石重贵的宠姬，个人名字与生卒年未载。949年石重贵迁到建州后不久，与赵氏一起被述律王耶律璟派骑兵带走。没有据此认定她与耶律璟建立婚姻关系。", "biography": null, "status": "draft", "id": "aea89584-5cf6-5147-adf4-ef294d136309"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "史德珫", "aliases": ["史德充"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "史弘肇的儿子，归德牙内指挥使。949年三月己未领忠州刺史。史书记他读过一些书，常不赞同父亲的做法，并劝父亲释放被送到侍卫司的举人。《旧五代史》写史德充，按父子身份、官职和同一事件对应识别。生卒年未载。", "biography": null, "status": "draft", "id": "7853100a-7d0a-5750-8e27-bae522cf63f4"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "徐进", "aliases": ["徐進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国将领。949年《通鉴》三月条记他在风阳山击败南方部族武装，《旧五代史》五月条记湖南奏报，称他为大将军并记援贺州。生卒年及族属未载。", "biography": null, "status": "draft", "id": "7fb77b1a-b802-5203-b8fa-46e851ebb401"}, {"name": "吴虔裕", "aliases": ["吳虔裕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉河中行营都监。949年四月奉郭威之命，率兵从侧面攻击李守贞出城部队，击败对方并夺取攻城器具。生卒年尚未确定。", "biography": null, "status": "draft", "id": "e576a210-c5b6-5c62-8309-4f25ed7f2693"}, {"name": "魏延朗", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李守贞的部将。949年五月李守贞再次出兵失败时，与郑宾一起被后汉军擒获。生卒年及被俘后的处置尚未确定。", "biography": null, "status": "draft", "id": "220af429-7356-5ee7-9b16-bef570726569"}, {"name": "郑宾", "aliases": ["鄭賓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李守贞的部将。949年五月李守贞再次出兵失败时，与魏延朗一起被后汉军擒获。生卒年及被俘后的处置尚未确定。", "biography": null, "status": "draft", "id": "3663049c-8930-5ad4-8048-a3602c47772f"}, {"name": "周光逊", "aliases": ["周光遜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李守贞的副使。948年十二月在河中与王继勋、聂知遇守城西。生卒年尚未确定。", "biography": null, "status": "draft", "id": "03d0befb-90fd-54e1-a23a-929e067d849d"}, {"name": "聂知遇", "aliases": ["聶知遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李守贞的裨将。948年十二月与周光逊、王继勋守河中城西。生卒年未载。", "biography": null, "status": "draft", "id": "93911802-b076-5027-80b6-c447c4fb93a7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

